async resolveWebviewView(view: IWebviewPanel): Promise<void> {
	this.view = view;
	view.onDidDispose(() => {
		if (this.view === view) this.view = undefined;
	});
	view.webview.onDidReceiveMessage?.((message: unknown) =>
		this.handleMessage(message),
	);
	await this.refresh();
}

